// Screenshots for the README: renders an "AI-generated landing page" with headless Edge as the sample image, starts a test instance with the English UI,
// draws marks and writes notes through CDP for real (the snapshots and REVIEW.md are generated by the app itself), and saves screenshots of the main window to docs/images/
// (the English pass also records an animated GIF, main-window.gif, which needs ffmpeg).
//   pwsh -File scripts/build-app.ps1 -Out $env:TEMP\sniptoss-shots     first build a copy of the app for testing (leaves the installed one alone)
//   node scripts/readme-shots.mjs $env:TEMP\sniptoss-shots\SnipToss.exe
// Doesn't touch the everyday settings (SNIPTOSS_SETTINGS points to a temp folder) or the clipboard (nothing is copied). Opens a window on screen and closes it when done

import { spawn, spawnSync } from "node:child_process";
import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "@playwright/test";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const exe = process.argv[2];
if (!exe || !existsSync(exe)) {
  console.error("Usage: node scripts/readme-shots.mjs <SnipToss.exe> (build it first with pwsh -File scripts/build-app.ps1 -Out <folder>)");
  process.exit(2);
}
const OUT = join(ROOT, "docs", "images");
mkdirSync(OUT, { recursive: true });

// Put the project under %TEMP%\Projects: the Library subtitle shows the containing folder ("…\Temp\Projects"), so no other path is exposed
const temp = join(tmpdir(), "Projects");
rmSync(temp, { recursive: true, force: true });
const project = join(temp, "slow-pour-site");
mkdirSync(join(project, "assets"), { recursive: true });

// ---------- Sample image: a landing page that looks AI-generated (headline too thin, wrong button color, a watermark in the corner - for the notes to point out) ----------
const hero = `<!doctype html><html><head><style>
  * { margin: 0; box-sizing: border-box; }
  body { width: 1600px; height: 1000px; font-family: "Segoe UI Variable Display", "Segoe UI", sans-serif; color: #2b1d14;
         background: radial-gradient(1200px 700px at 78% 40%, #f3d9b9 0%, #f7ebdc 45%, #fbf6ef 100%); overflow: hidden; position: relative; }
  nav { position: absolute; top: 48px; left: 96px; right: 96px; display: flex; align-items: center; justify-content: space-between; font-size: 22px; }
  nav .logo { font-weight: 700; letter-spacing: 0.04em; }
  nav .links { display: flex; gap: 40px; color: #6b5444; }
  h1 { position: absolute; top: 250px; left: 96px; width: 760px; font-size: 92px; line-height: 1.02; font-weight: 200; letter-spacing: -0.02em; }
  p { position: absolute; top: 500px; left: 100px; width: 600px; font-size: 26px; line-height: 1.5; color: #6b5444; }
  .cta { position: absolute; top: 640px; left: 100px; padding: 22px 44px; border-radius: 999px; background: #e0338a; color: #fff; font-size: 24px; font-weight: 600; }
  .ghost { position: absolute; top: 646px; left: 380px; font-size: 22px; color: #6b5444; padding: 18px 8px; }
  .cup { position: absolute; left: 980px; top: 230px; width: 460px; height: 460px; border-radius: 50%;
         background: radial-gradient(circle at 50% 50%, #4a2c1a 0 52%, #6b3f25 53% 58%, #f4ede4 59% 66%, #e7dccd 67% 100%);
         box-shadow: 0 60px 120px rgba(74, 44, 26, 0.35); }
  .cup::after { content: ""; position: absolute; left: 150px; top: 150px; width: 160px; height: 160px; border-radius: 50%;
                border: 10px solid rgba(244, 237, 228, 0.55); border-color: rgba(244,237,228,0.55) transparent transparent rgba(244,237,228,0.55); transform: rotate(-20deg); }
  .saucer { position: absolute; left: 920px; top: 660px; width: 580px; height: 90px; border-radius: 50%; background: #e7dccd; filter: blur(0.3px); }
  .mark { position: absolute; right: 70px; top: 130px; font-size: 40px; font-weight: 700; color: rgba(43, 29, 20, 0.18); transform: rotate(-12deg); letter-spacing: 0.3em; }
</style></head><body>
  <nav><div class="logo">SLOW POUR</div><div class="links"><span>Beans</span><span>Brew guides</span><span>Visit us</span></div></nav>
  <h1>Coffee, brewed slowly.</h1>
  <p>Small-batch beans roasted every Monday and delivered to your door within the week.</p>
  <div class="cta">Start a subscription</div><div class="ghost">See this week's beans →</div>
  <div class="saucer"></div><div class="cup"></div>
  <div class="mark">STOCKPHOTO</div>
</body></html>`;
const browser = await chromium.launch({ channel: "msedge" });
const render = await browser.newPage({ viewport: { width: 1600, height: 1000 } });
await render.setContent(hero);
await render.screenshot({ path: join(project, "assets", "hero.png") });
// The second image (banner) carries one note that is already resolved. With a note already in the project, the hint saying where notes are stored
// (with the full path) doesn't appear when the first note is written
await render.setViewportSize({ width: 1600, height: 500 });
await render.setContent(
  hero
    .replace("<h1>Coffee, brewed slowly.</h1>", '<h1 style="top:150px;font-weight:700">New beans every Monday.</h1>')
    .replace(/<p>[^<]*<\/p>/, ""),
);
await render.screenshot({ path: join(project, "assets", "banner.png") });
await browser.close();
const bannerSha = createHash("sha256")
  .update(readFileSync(join(project, "assets", "banner.png")))
  .digest("hex");
const seed = (dir) => {
  mkdirSync(join(dir, ".sniptoss", "annotations"), { recursive: true });
  const at = "2026-10-20T02:00:00Z";
  writeFileSync(
    join(dir, ".sniptoss", "annotations", "assets__banner.png.json"),
    JSON.stringify(
      {
        schema: "sniptoss/4",
        material: { path: "assets/banner.png", kind: "image", sha256: bannerSha, width: 1600, height: 500 },
        annotations: [
          {
            id: "b4nn3r",
            status: "resolved",
            category: "change",
            body: "Make the headline bold.",
            anchor: {},
            author: "user",
            created_at: at,
            updated_at: at,
            replies: [],
          },
        ],
      },
      null,
      2,
    ) + "\n",
  );
};

// ---------- One test instance per language: only this project, window 1280 × 800 ----------
const NOTES = {
  en: [
    "Title is too thin and gets lost on the background. Use a bold weight.",
    "Button color doesn't match the brand. Use the coffee brown #6B3F25.",
    "Remove the stock watermark.",
  ],
  "zh-CN": ["标题字太细，压在背景上看不清，改成粗体。", "按钮颜色和品牌不搭，改成咖啡棕 #6B3F25。", "去掉图库水印。"],
};
const wait = async (what, fn, ms = 30_000) => {
  for (const end = Date.now() + ms; Date.now() < end; await new Promise((r) => setTimeout(r, 200))) {
    const v = await fn();
    if (v) return v;
  }
  throw new Error(`Timed out waiting for: ${what}`);
};

/** Assembles the recorded frames into an animated GIF: ffmpeg joins them with each frame's duration (concat), scaled to 960 wide, 128-color palette, looping */
function writeGif(frames, out) {
  const dir = join(temp, "frames");
  mkdirSync(dir, { recursive: true });
  const list = [];
  frames.forEach((f, i) => {
    const name = `f${String(i).padStart(5, "0")}.png`;
    writeFileSync(join(dir, name), Buffer.from(f.data, "base64"));
    const next = frames[i + 1]?.t ?? f.t + 2.5; // hold the last frame a little longer before looping
    list.push(`file '${name}'`, `duration ${Math.max(0.02, next - f.t).toFixed(3)}`);
  });
  list.push(`file 'f${String(frames.length - 1).padStart(5, "0")}.png'`); // concat quirk: the last frame must be listed again for its duration to count
  writeFileSync(join(dir, "list.txt"), list.join("\n") + "\n");
  const r = spawnSync(
    "ffmpeg",
    [
      "-v",
      "error",
      "-y",
      "-f",
      "concat",
      "-safe",
      "0",
      "-i",
      "list.txt",
      "-vf",
      "fps=15,scale=960:-1:flags=lanczos,split[a][b];[a]palettegen=max_colors=128:stats_mode=diff[p];[b][p]paletteuse=dither=bayer:bayer_scale=4:diff_mode=rectangle",
      "-loop",
      "0",
      out,
    ],
    { cwd: dir, encoding: "utf8" },
  );
  if (r.status !== 0) throw new Error(`ffmpeg failed to build the GIF: ${r.stderr}`);
  console.log(`Saved: ${out} (${frames.length} frames)`);
}
/** gif: also record the process of writing the notes as an animated GIF (same name with .gif under docs/images); typing and dragging are slowed down so people can follow */
async function shoot(locale, file, gif = false) {
  const data = join(temp, `instance-${locale}`);
  mkdirSync(data, { recursive: true });
  rmSync(join(project, ".sniptoss"), { recursive: true, force: true }); // every language starts from the same state: only the resolved note on the banner
  seed(project);
  const settings = join(data, "settings.json");
  writeFileSync(
    settings,
    JSON.stringify({
      Library: [{ Path: project, Pinned: false }],
      Expanded: [join(project, "assets")],
      Placement: { Left: 60, Top: 60, Width: 1280, Height: 800 },
      Prefs: { language: locale, onboarding: ["tour", "hint.copy", "hint.video"] }, // mark the tour and hints as seen so they aren't in the screenshots
      Capture: { Hotkey: "", KeepInTray: false, TrayHintShown: true },
      Migrations: 1,
    }),
  );
  const proc = spawn(exe, [], {
    env: { ...process.env, SNIPTOSS_SETTINGS: settings, WEBVIEW2_ADDITIONAL_BROWSER_ARGUMENTS: "--remote-debugging-port=0" },
    stdio: "ignore",
  });
  const portFile = join(data, "WebView2", "EBWebView", "DevToolsActivePort");
  try {
    const port = await wait("debugging port", () => existsSync(portFile) && Number(readFileSync(portFile, "utf8").split("\n")[0]));
    const app = await chromium.connectOverCDP(`http://127.0.0.1:${port}`);
    const page = await wait("UI", () =>
      app
        .contexts()
        .flatMap((c) => c.pages())
        .find((p) => !p.url().startsWith("edge://")),
    );
    await page.locator(".lib-row", { hasText: "hero.png" }).click();
    await page.waitForTimeout(1500); // the image loads and fits the window
    const frames = [];
    let cdp;
    if (gif) {
      // CDP screencast: a frame arrives only when the page changes, with a timestamp; the timestamps give each frame's duration when assembling
      cdp = await page.context().newCDPSession(page);
      cdp.on("Page.screencastFrame", ({ data: png, metadata, sessionId }) => {
        frames.push({ data: png, t: metadata.timestamp });
        cdp.send("Page.screencastFrameAck", { sessionId }).catch(() => {});
      });
      await cdp.send("Page.startScreencast", { format: "png", everyNthFrame: 1 });
      await page.mouse.move(700, 420);
      await page.waitForTimeout(1200);
    }
    const slow = gif ? { steps: 30, type: 45, after: 1100 } : { steps: 12, type: 8, after: 600 };

    /** Draw a mark on the image and write a note: tool is the tool key, from / to are positions on the image as fractions */
    const note = async (tool, from, to, text, category) => {
      await page.locator(".stage").click({ position: { x: 4, y: 4 } });
      await page.keyboard.press(tool);
      await page.locator(".annot-input").waitFor();
      const box = await page.locator("img.zoom-media").boundingBox(); // the image itself (the canvas is larger than it)
      const at = ([x, y]) => [box.x + box.width * x, box.y + box.height * y];
      const [x1, y1] = at(from);
      await page.mouse.move(x1, y1);
      await page.mouse.down();
      if (to) {
        const [x2, y2] = at(to);
        await page.mouse.move(x2, y2, { steps: slow.steps });
      }
      await page.mouse.up();
      await page
        .locator(".composer-text")
        .waitFor({ timeout: 8000 })
        .catch(async (e) => {
          await page.screenshot({ path: join(tmpdir(), "readme-shots-failed.png") });
          throw new Error(`The note "${text}" did not open the note box (screenshot: %TEMP%\\readme-shots-failed.png): ${e.message}`);
        });
      if (category) await page.keyboard.press(`Alt+${category}`);
      await page.locator(".composer-text").pressSequentially(text, { delay: slow.type });
      await page.keyboard.press("Enter");
      await page.waitForTimeout(slow.after);
    };
    const [title, button, mark] = NOTES[locale];
    await note("r", [0.055, 0.235], [0.54, 0.44], title);
    await note("a", [0.36, 0.8], [0.25, 0.68], button);
    await note("c", [0.88, 0.17], null, mark, 2);
    // The toast shown when the first note is written in a project says where notes are stored (with the full path): wait for it to dismiss itself
    // (don't click its Open button, that would open File Explorer); if it is still there, remove it from the page
    await page
      .locator(".toast")
      .waitFor({ state: "detached", timeout: 15_000 })
      .catch(() => page.evaluate(() => document.querySelectorAll(".toast").forEach((t) => t.remove())));
    // Back to the Select tool and select the first note: it is highlighted on the canvas and in the notes panel
    await page.keyboard.press("v");
    await page.locator("[data-annot]").first().click();
    await page.mouse.move(10, 790);
    await page.waitForTimeout(800);
    await page.screenshot({ path: join(OUT, file) });
    console.log(`Saved: ${join(OUT, file)}`);
    if (gif) {
      await page.waitForTimeout(1500);
      await cdp.send("Page.stopScreencast");
      writeGif(frames, join(OUT, file.replace(/\.png$/, ".gif")));
    }
    await app.close();
  } finally {
    spawnSync("taskkill", ["/PID", String(proc.pid), "/T", "/F"], { stdio: "ignore" });
    await new Promise((r) => setTimeout(r, 1500));
  }
}

try {
  await shoot("en", "main-window.png", true);
  await shoot("zh-CN", "main-window.zh-CN.png");
} finally {
  rmSync(temp, { recursive: true, force: true, maxRetries: 20, retryDelay: 250 });
}
